import React, { useRef, useState, useEffect, useContext } from 'react'
import '../style/tour-detail.css'
import { Container, Row, Col, Form, ListGroup } from 'reactstrap'
import { useParams } from 'react-router-dom'
import caculateAvgRating from '../utils/avgRating'
import avatar from "../assets/images/avatar.jpg"
import Booking from '../components/Booking/Booking'
import Newsletter from '../share/Newsletter'
import useFetch from '../hooks/useFetch'
import { BASE_URL } from '../utils/config'
import { AuthContext } from '../context/AuthContext'

const TourDetails = () => {
  const { id } = useParams()
  const reviewMsgRef = useRef('')
  const [tourRating, setTourRating] = useState(null)
  const { user } = useContext(AuthContext)

  // Gọi API lấy dữ liệu
  const { data: result, loading, error } = useFetch(`${BASE_URL}/tours/${id}`)

  /* 
     XỬ LÝ DỮ LIỆU: 
     Vì log của bạn báo 'result' là [], ta cần kiểm tra:
     Nếu result là mảng và có phần tử, lấy phần tử đầu tiên.
     Nếu result là object (đúng chuẩn), lấy result.
  */
  const tour = Array.isArray(result) ? (result.length > 0 ? result[0] : null) : result;

  // Debug để bạn theo dõi trong console
  console.log("Dữ liệu tour sau khi xử lý:", tour);

  const [selectedImg, setSelectedImg] = useState(null)

  useEffect(() => {
    window.scrollTo(0, 0)
    if (tour?.photo) setSelectedImg(tour.photo)
  }, [tour])

  // Nếu đang load hoặc có lỗi hoặc chưa có dữ liệu tour
  if (loading) return <h4 className='text-center pt-5'>Đang tải dữ liệu...</h4>
  if (error) return <h4 className='text-center pt-5'>{error}</h4>
  if (!tour || Object.keys(tour).length === 0) {
    return <h4 className='text-center pt-5'>Không tìm thấy dữ liệu tour (ID: {id})</h4>
  }

  // Destructuring sau khi đã đảm bảo tour có dữ liệu
  const { 
    photo, title, desc, price, address, reviews, 
    city, distance, maxGroupSize, images, itinerary 
  } = tour

  const { totalRating, avgRating } = caculateAvgRating(reviews || [])
  const options = { day: 'numeric', month: 'long', year: 'numeric' }

  const submitHandler = async e => {
    e.preventDefault()
    const reviewText = reviewMsgRef.current.value
    const token = localStorage.getItem('token')

    try {
      if (!user) return alert('Bạn chưa đăng nhập')

      const reviewObj = {
        username: user?.username,
        reviewText,
        rating: tourRating
      }
      const res = await fetch(`${BASE_URL}/review/${id}`, {
        method: 'post',
        headers: {
          'content-type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(reviewObj)
      })

      const resResult = await res.json()
      if (!res.ok) return alert(resResult.message)
      alert(resResult.message)
      window.location.reload()
    } catch (err) {
      alert(err.message)
    }
  }

  return (
    <>
      <section>
        <Container>
          <Row>
            <Col lg='8'>
              <div className="tour_content">
                {/* Ảnh chính */}
                <img 
                  src={`${BASE_URL}/static-number-one/${selectedImg || photo}`} 
                  alt={title} 
                  style={{ width: '100%', borderRadius: '0.5rem' }}
                />
                
                {/* Bộ sưu tập ảnh nhỏ */}
                <div className="tour__gallery d-flex gap-2 mt-3">
                  {images?.map((img, index) => (
                    <img
                      key={index}
                      src={`${BASE_URL}/static-number-one/${img}`}
                      alt=""
                      onClick={() => setSelectedImg(img)}
                      style={{
                        width: '100px',
                        height: '80px',
                        objectFit: 'cover',
                        borderRadius: '5px',
                        cursor: 'pointer',
                        border: selectedImg === img ? '2px solid #ff7e1a' : '1px solid #ccc'
                      }}
                    />
                  ))}
                </div>

                <div className="tour_info">
                  <h2>{title}</h2>

                  <div className='d-flex align-items-center gap-5'>
                    <span className='tour_rating d-flex align-items-center gap-1'>
                      <i className="ri-star-fill" style={{ color: "var(--secondary-color)" }}></i> 
                      {avgRating === 0 ? null : avgRating}
                      {totalRating === 0 ? "Chưa có đánh giá" : <span>({reviews?.length})</span>}
                    </span>

                    <span><i className="ri-map-pin-line"></i>{address}</span>
                  </div>

                  <div className="tour_extra-details">
                    <span><i className="ri-road-map-line"></i>{city}</span>
                    <span><i className="ri-money-dollar-circle-line"></i>{Number(price).toLocaleString('vi-VN')}đ</span>
                    <span><i className="ri-route-line"></i>{distance}km</span>
                    <span><i className="ri-group-fill"></i>{maxGroupSize} người</span>
                  </div>

                  <h5 className='mt-4'>Mô tả</h5>
                  <p>{desc}</p>

                  {/* HIỂN THỊ LỊCH TRÌNH CHI TIẾT */}
                  <div className="tour__itinerary mt-5">
                    <h5 className='mb-4'>Lịch trình chi tiết</h5>
                    <div className="itinerary__list">
                      {itinerary && itinerary.length > 0 ? (
                        itinerary.map((item, index) => (
                          <div className="itinerary__item mb-4" key={index} 
                               style={{ borderLeft: '2px dashed #ff7e1a', paddingLeft: '20px', marginLeft: '10px' }}>
                            <div className="d-flex align-items-center gap-3">
                              <span style={{ background: '#ff7e1a', color: '#fff', padding: '2px 10px', borderRadius: '15px', fontSize: '0.8rem' }}>
                                Ngày {item.day}
                              </span>
                              <h6 className='mb-0'>{item.location}</h6>
                            </div>
                            <p className="mt-2 text-muted">{item.description}</p>
                            {item.meals && (
                              <small className="d-block text-primary">
                                <i className="ri-restaurant-2-line"></i> Bữa ăn: {item.meals}
                              </small>
                            )}
                          </div>
                        ))
                      ) : (
                        <p className='text-muted italic'>Lịch trình hiện đang được cập nhật...</p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Phần Review */}
                <div className="tour_reviews mt-4">
                  <h4>Đánh giá ({reviews?.length} nhận xét)</h4>
                  <Form onSubmit={submitHandler}>
                    <div className='d-flex align-items-center gap-3 mt-4 rating_group'>
                      {[1, 2, 3, 4, 5].map(num => (
                        <span key={num} onClick={() => setTourRating(num)}>
                          {num}<i className="ri-star-fill"></i>
                        </span>
                      ))}
                    </div>
                    <div className="review_input">
                      <input type="text" ref={reviewMsgRef} placeholder='Chia sẻ trải nghiệm của bạn' required />
                      <button className='btn primary_btn text-white' type='submit'>Gửi</button>
                    </div>
                  </Form>

                  <ListGroup className='user_reviews mt-4'>
                    {reviews?.map((review, index) => (
                      <div className="review_item" key={index}>
                        <img src={avatar} alt="" />
                        <div className="w-100">
                          <div className='d-flex align-items-center justify-content-between'>
                            <div>
                              <h5>{review.username}</h5>
                              <p>{new Date(review.createdAt).toLocaleDateString('vi-VN', options)}</p>
                            </div>
                            <span className='d-flex align-items-center'>{review.rating}<i className="ri-star-fill"></i></span>
                          </div>
                          <h6>{review.reviewText}</h6>
                        </div>
                      </div>
                    ))}
                  </ListGroup>
                </div>
              </div>
            </Col>

            <Col lg='4'>
              <Booking tour={tour} avgRating={avgRating} />
            </Col>
          </Row>
        </Container>
      </section>
      <Newsletter />
    </>
  )
}

export default TourDetails
